// Init Deploy: the launch row into the run's state. The Alta door's contract is the PlusVibe
// door's, one launch = one view into one campaign: Client link, Table ID, View (name), Target
// (the Alta campaign UUID). Dedupe here is the Campaigns-stamp gate plus readback, there is no
// sequencer-side dedupe mode to choose.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
const r=($input.first()||{}).json||{};
const f=r.fields||r;
const clientIds=Array.isArray(f['Client'])?f['Client']:[];
const cid=clientIds[0];
const D={launchId:r.id||'', clientId:(cid&&typeof cid==='object')?String(cid.id||''):String(cid||''), tableId:String(f['Table ID']||'').trim(), view:String(f['View']||'').trim(), target:String(f['Target']||'').trim(), ws:'', crBase:'', clientName:'', tableName:'', campName:'', pullInUrl:'', mirrorTableId:'', stampMirrorRid:'', shareViewLink:'', errors:[], warnings:[], skipCounts:{}, rows:{}, rowsTotal:0, pushed:0, landed:0, missing:0, pausedTitle:0, abort:null, startedAt:Date.now(), runAt:$now.toISO()};
if(!D.launchId){ D.abort='launch row not found'; D.errors.push('launch row not found (recordId missing or invalid)'); }
if(!D.abort&&!D.clientId){ D.abort='no client link'; D.errors.push('launch row has no Client link'); }
if(!D.abort&&!/^tbl[A-Za-z0-9]{14}$/.test(D.tableId)){ D.abort='no Table ID'; D.errors.push('launch row has no valid Table ID'); }
if(!D.abort&&!D.view){ D.abort='no View'; D.errors.push('launch row has no View'); }
if(!D.abort&&!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(D.target)){ D.abort='invalid Target'; D.errors.push('Target "'+D.target+'" is not an Alta campaign UUID'); }
sd[dk]=D;
return [{json:{clientId:D.clientId||'recMISSING'}}];

// Check Client: the registry row into the run's state. The ClayRoots base is the address of
// the table the view lives on; nothing about a client is hardcoded anywhere in this machine.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(!D.abort){
  const r=($input.first()||{}).json||{};
  const f=r.fields||r;
  D.clientName=String(f['Client']||'').trim();
  D.crBase=String(f['Clayroots Base ID']||'').trim();
  if(!/^app[A-Za-z0-9]{14}$/.test(D.crBase)){ D.abort='no ClayRoots base'; D.errors.push('client "'+(D.clientName||D.clientId)+'" has no valid Clayroots Base ID'); }
}
return [{json:{abort:!!D.abort, target:D.target||''}}];

// Check Campaign: the Hub Campaigns row for the target. Two hard facts come from it:
// the campaign is an Alta campaign, and its Pull-in URL (the audience webhook Alta hands out
// per campaign; no API exposes it, so it is operator-pasted state on the campaign row).
// No row, wrong sequencer, or no Pull-in URL = abort before anything is sent.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(!D.abort){
  const rows=$input.all().map(i=>i.json).filter(r=>r&&(r.id||r.fields));
  const hit=rows[0];
  if(!hit){ D.abort='campaign not in Hub'; D.errors.push('no Campaigns row with Campaign ID '+D.target+'; sync or create it first'); }
  else{
    const f=hit.fields||hit;
    D.hubCampaignRid=hit.id||'';
    D.campName=String(f['Campaign']||D.target);
    const seq=String((f['Sequencer']&&f['Sequencer'].name)||f['Sequencer']||'');
    if(seq&&seq!=='Alta'){ D.abort='not an Alta campaign'; D.errors.push('campaign "'+D.campName+'" is sequenced by '+seq+', not Alta'); }
    D.pullInUrl=String(f['Pull-in URL']||'').trim();
    if(!D.abort&&!/^https:\/\/api\.altahq\.com\/audience\/webhook\/[0-9a-f-]+\/pull-in-prospect$/i.test(D.pullInUrl)){
      D.abort='no Pull-in URL'; D.errors.push('campaign "'+D.campName+'" has no valid Pull-in URL on its Campaigns row; paste the audience webhook from Alta');
    }
  }
}
return [{json:{abort:!!D.abort, crBase:D.crBase||'', target:D.target||'', metaUrl:'https://api.airtable.com/v0/meta/bases/'+(D.crBase||'missing')+'/tables'}}];

// Plan View: the base schema into the run's plan. Resolves the table, the view by exact name,
// the campaigns mirror table (Campaign ID + Sequencer, no Final Email; same signature the
// PV->CR sync uses), and the client share link from the table description (the receipt's
// List URL; its absence is a warning here, never sent to clients silently).
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{viewUrl:'', rowsUrl:''}}]; }
let tables=[];
try{ const j=($input.first()||{}).json||{}; tables=Array.isArray(j.tables)?j.tables:[]; }catch(e){}
const t=tables.find(x=>x.id===D.tableId);
if(!t){ D.abort='table not found'; D.errors.push('table '+D.tableId+' not in base '+D.crBase); return [{json:{viewUrl:'', rowsUrl:''}}]; }
D.tableName=t.name||D.tableId;
const m=String(t.description||'').match(/https:\/\/airtable\.com\/[^\s")]+\/shr[A-Za-z0-9]+/);
D.shareViewLink=m?m[0]:'';
if(!D.shareViewLink) D.warnings.push('table description carries no share link; receipt written without a client link');
// The launch's View accepts a view id (viw...) or an exact name; ids are rename-proof and
// the Signal View convention on Campaigns holds ids (Operator ruling 2026-08-31).
const v=(t.views||[]).find(x=>x.id===D.view||String(x.name)===D.view);
if(!v){ D.abort='view not found'; D.errors.push('view "'+D.view+'" not on table "'+D.tableName+'"'); return [{json:{viewUrl:'', rowsUrl:''}}]; }
D.viewId=v.id;
const mirT=tables.find(x=>{ const ns=new Set((x.fields||[]).map(f=>f.name)); return !ns.has('Final Email')&&ns.has('Campaign ID')&&ns.has('Sequencer'); });
D.mirrorTableId=mirT?mirT.id:'';
if(!D.mirrorTableId) D.warnings.push('no campaigns mirror table in base; Campaigns links cannot be stamped');
D.fieldsById={}; const names=new Set(); for(const f of (t.fields||[])){ D.fieldsById[f.id]=f.name; names.add(f.name); }
D.hasDeployError=names.has('Deploy Error');
if(!D.hasDeployError) D.warnings.push('table has no Deploy Error field; skip reasons are not written to rows');
return [{json:{viewUrl:'https://api.airtable.com/v0/meta/bases/'+D.crBase+'/views/'+D.viewId+'?include=visibleFieldIds', rowsUrl:'https://api.airtable.com/v0/'+D.crBase+'/'+D.tableId+'?view='+D.viewId+'&pageSize=100'}}];

// Plan Contract: THE RULE, the PlusVibe door's doctrine on the Alta side. The view's visible
// columns are the contract: machine fields never sent, convention (never-block) fields sent
// when filled, every other visible column a REQUIRED variable (extraInfoData). Identity here
// is LinkedIn URL + first_name + Company; Final Email rides along when present, never blocks.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{ok:false, crBase:D.crBase||'appMISSING', mirrorTableId:'tblMISSING', target:D.target||''}}]; }
let vm={};
try{ vm=($input.first()||{}).json||{}; }catch(e){}
const visibleIds=Array.isArray(vm.visibleFieldIds)?vm.visibleFieldIds:null;
if(!visibleIds){ D.warnings.push('view metadata unavailable ('+String(vm.error?JSON.stringify(vm.error).slice(0,120):'no visibleFieldIds')+'); only identity is enforced and no variables are sent'); }
const MACHINE=new Set(['Status','MV','MV P0','MV P1','MV P2','MV P3','BB','P1','P2','P3','P1 (Trykitt)','P2 (LeadMagic)','P3 (Prospeo)','Source','Email Source','Contact Source','Contact Key','Run ID','Build Date','Created','Seniority Rank','segment','query_name','ingested_at','RankInCompany','Co Rank','Campaign Segment','reloaded_patch','manually_approved','relevance','public_emails_clean','Email','Domain','Campaigns','Campaigns (old text)','Messages Sent','Last Contacted','Campaign Status','Bounce Reason','Synced At','Deploy Error','Name','Valid','Intent Status','LinkedIn Campaign','Email Campaign','LinkedIn Routed At','Email Routed At','Target Campaign','routed_at','Enroll Confirmed','Enroll Error','Event Type','Final Email','company_clean','First Hire','linkedin_name_match','Tag']);
const IGNORE=new Set(['last_name','Title','Social','Phone','MX Provider','MX provider','MX','LinkedIn URL','City','State','State Full','Country','Zip','Street','Seniority','Department','Existing In Role','ICP Reason','Description','Industry Groups','Employees','Revenue Range','Score','Keywords','Company Status','Start Date','Company City','Company State','Phones','Public Emails','Social URLs','Redirect Domain','Email Pattern','Signal Detail','detected_at']);
const IDENTITY=new Set(['first_name','Company']);
const neverBlock=(col)=>IGNORE.has(col)||/^job\s/i.test(String(col));
const varCols=[]; const rideCols=[];
if(visibleIds){
  for(const fid of visibleIds){
    const name=D.fieldsById[fid]; if(!name) continue;
    if(MACHINE.has(name)||IDENTITY.has(name)) continue;
    if(neverBlock(name)){ if(name!=='LinkedIn URL'&&name!=='last_name') rideCols.push(name); continue; }
    varCols.push(name);
  }
}
D.plan={varCols, rideCols};
D.fieldsById=null;
return [{json:{ok:true, crBase:D.crBase, tableId:D.tableId, viewName:D.view, mirrorTableId:D.mirrorTableId||'tblMISSING', target:D.target}}];

// Resolve Mirror: the campaign's mirror row in the client base, resolved BEFORE anything is
// sent, because it is both the stamp target and the stamp-gate (a row already linked to it
// never re-enters this campaign). Missing mirror row = created downstream before stamping.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
let rid='';
try{ const r=($input.first()||{}).json||{}; if(r.id) rid=r.id; }catch(e){}
D.stampMirrorRid=rid||'';
return [{json:{needMirror: !D.abort && !!D.mirrorTableId && !rid, mirrorTableId:D.mirrorTableId||'', crBase:D.crBase||'', campName:D.campName||'', target:D.target||''}}];

// Collect Mirror: the just-created mirror row's id becomes the stamp target.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
try{ const r=($input.first()||{}).json||{}; if(r.id) D.stampMirrorRid=r.id; }catch(e){}
if(!D.stampMirrorRid&&D.mirrorTableId) D.warnings.push('mirror row could not be created; Campaigns links not stamped this run');
return [{json:{mirrorRid:D.stampMirrorRid||''}}];

// Build Prospects: the view's rows into pull-in bodies, one item per prospect to push.
// Identity, hard: LinkedIn URL (this door's key) and Company (or company_clean); the name
// rides when present, Alta resolves the person from the URL.
// The stamp-gate: a row whose Campaigns links already carry this campaign's mirror row is
// skipped, the door's ONLY dedupe and the whole of it (Operator 2026-08-28: Alta relies
// solely on the stamp). Every required variable missing skips the row with its name.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{_none:true}}]; }
let rows=[];
try{ for(const it of $input.all()){ const j=it.json||{}; const recs=Array.isArray(j.records)?j.records:(j.id?[j]:[]); rows.push(...recs); } }catch(e){}
D.rowsTotal=rows.length;
if(!rows.length){ D.abort='view empty'; D.errors.push('view "'+D.view+'" returned no rows; nothing was sent'); return [{json:{_none:true}}]; }
const val=v=>{ if(v===null||v===undefined) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='number'||typeof v==='boolean') return String(v); if(Array.isArray(v)) return v.filter(x=>typeof x==='string'||typeof x==='number').join(', '); if(typeof v==='object'&&typeof v.value==='string') return v.value.trim(); if(typeof v==='object'&&typeof v.name==='string') return v.name; return ''; };
const snake=k=>String(k).replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase();
const normUrl=u=>String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,'').split('?')[0];
const plan=D.plan||{varCols:[],rideCols:[]};
D.rows={}; D.urlToRow={}; D.varMisses={};
const out=[];
for(const r of rows){
  const f=r.fields||{};
  const rec={skip:null, camps:Array.isArray(f['Campaigns'])?f['Campaigns']:[]};
  D.rows[r.id]=rec;
  const li=val(f['LinkedIn URL']);
  if(!/^https?:\/\//i.test(li)){ rec.skip='missing LinkedIn URL'; continue; }
  rec.url=normUrl(li);
  if(D.stampMirrorRid&&rec.camps.indexOf(D.stampMirrorRid)>=0){ rec.skip='already in campaign (Campaigns stamp)'; continue; }
  if(D.urlToRow[rec.url]){ rec.skip='duplicate LinkedIn URL in view (row '+D.urlToRow[rec.url]+' already queued)'; continue; }
  // first_name is NOT identity here (Operator 2026-08-31): Alta resolves the person from the
  // LinkedIn URL, so the name rides along when present and never blocks.
  const fn=val(f['first_name']);
  const comp=val(f['company_clean'])||val(f['Company']); if(!comp){ rec.skip='missing company name'; continue; }
  const extra={}; const missing=[];
  for(const col of plan.varCols){ const v=val(f[col]); if(v) extra[snake(col)]=v.length>4000?v.slice(0,4000):v; else missing.push(col); }
  if(missing.length){ for(const m of missing) D.varMisses[m]=(D.varMisses[m]||0)+1; rec.skip='missing '+missing.join(', ').slice(0,120); continue; }
  for(const col of plan.rideCols){ const v=val(f[col]); if(v) extra[snake(col)]=v.length>4000?v.slice(0,4000):v; }
  const body={ company:comp, linkedinUrl:li, extraInfoData:extra };
  if(fn) body.firstName=fn;
  const ln=val(f['last_name']); if(ln) body.lastName=ln;
  const dom=val(f['Domain']); if(dom) body.companyWebsite=/^https?:\/\//i.test(dom)?dom:'https://'+dom;
  const email=val(f['Final Email']); if(email) body.email=email;
  D.urlToRow[rec.url]=r.id;
  out.push({json:{recordId:r.id, enroll_body:body, campaign_url:D.pullInUrl}});
}
const skipCounts={};
for(const id of Object.keys(D.rows)){ const s=D.rows[id].skip; if(s){ const key=s.indexOf('missing ')===0?s:(s.indexOf('DNC')===0?'DNC':s); skipCounts[key]=(skipCounts[key]||0)+1; } }
D.skipCounts=skipCounts;
if(!out.length) return [{json:{_none:true}}];
return out;

// Collect Push: the pull-in responses, per prospect. Alta answers 200 even for pushes it later
// drops (a paused campaign swallows pull-ins silently, proven live 2026-08-27), so a 200 here
// counts only as "sent"; landing is decided by the readback, never by this response.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
let sent=0, failed=0;
const items=$input.all();
const pushed=[];
try{ for(const it of $('Build Prospects').all()){ const j=it.json||{}; if(j.recordId) pushed.push(j.recordId); } }catch(e){}
items.forEach((it,i)=>{
  const j=it.json||{};
  const status=Number(j.statusCode)||((j.error)?0:200);
  const rid=pushed[i];
  if(status>=200&&status<300){ sent++; }
  else{ failed++; if(rid&&D.rows[rid]) D.rows[rid].skip='push failed HTTP '+status; }
});
D.pushed=sent;
if(failed) D.warnings.push(failed+' pull-in push(es) failed with a non-2xx status');
return [{json:{sent, failed, campaignId:D.target}}];

// Verify Landing: the campaign's live prospect list after the pushes. Alta's pull-in answers
// 200 and can still drop the prospect (paused campaign, proven 2026-08-27), so landing is
// decided HERE by values. Fresh prospects (created since run start) are the primary
// candidates; if pushed rows remain unaccounted for, the WHOLE membership is resolved
// (capped) so a row that landed in an earlier crashed run is recognized and STAMPED instead
// of being re-pushed every day forever - the crash-hole closed 2026-08-31.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{_none:true, personIds:[]}}]; }
let rows=[];
try{ const j=($input.first()||{}).json||{}; rows=Array.isArray(j.rows)?j.rows:[]; }catch(e){}
D.campaignProspects=rows.length;
const since=new Date((D.startedAt||Date.now())-10*60*1000).toISOString();
D.freshProspects={};
const freshIds=[]; const oldIds=[];
for(const p of rows){
  if(!p.personId) continue;
  if(String(p.createdAt||'')>=since){ D.freshProspects[p.personId]={prospectId:p.prospectId}; freshIds.push(p.personId); }
  else oldIds.push(p.personId);
}
let personIds=freshIds.slice(0,300);
// Pushed more than fresh accounts for? A prior run may have landed rows it never stamped.
if(D.pushed>freshIds.length&&oldIds.length){
  D.fallbackUsed=true;
  personIds=personIds.concat(oldIds.slice(0,Math.max(0,500-personIds.length)));
  D.warnings.push('pushed '+D.pushed+' but only '+freshIds.length+' fresh prospects; resolving '+Math.min(oldIds.length,500-freshIds.length)+' older members to heal unstamped landings');
}
if(freshIds.length>300) D.warnings.push('readback capped at 300 fresh prospects of '+freshIds.length);
if(!personIds.length){
  if(D.pushed) D.warnings.push('pushed '+D.pushed+' but the campaign shows no prospects at all; Alta may have dropped them (is the campaign paused?)');
  return [{json:{_none:true, personIds:[]}}];
}
return [{json:{personIds}}];

// Title Gate: Alta's OWN enriched person data against the buyer rule, after landing. Alta
// stores its own title for a person, and it can disagree with ours; nothing that checks only
// our side can catch that (the Lewin Joey incident, 2026-08-27). The rule here mirrors the
// `relevance` formula on the intent tables; a landed prospect whose Alta-side title fails it
// is paused by the next node before a message can go out, and named in the run log.
// Identity too: a person whose Alta LinkedIn URL is not the URL we pushed is paused.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{prospectIds:[], action:'pause', _none:true}}]; }
let persons=[];
try{ const j=($input.first()||{}).json||{}; persons=Array.isArray(j.rows)?j.rows:[]; }catch(e){}
const normUrl=u=>String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,'').split('?')[0];
const roleOnly=t=>{ let s=String(t||''); s=s.split(/\s+\|\s+|\s+@\s+/)[0]; s=s.replace(/\s+at\s+[^|]*$/i,''); return s.trim(); };
const EXEC=/\b(founder|founding|co-?founder|owner|ceo|cto|cio|ciso|coo|president|chief)\b/i;
const LEAD=/\b(vp|svp|evp|vice president|head|director|manager|lead|principal|staff)\b/i;
const TECH=/\b(engineering|engineer|technology|technical|infrastructure|infra|platform|devops|sre|site reliability|cloud|security|information security|it|software|systems|architecture|architect|data|product)\b/i;
const IC=/\b(devops|site reliability|sre|platform engineer|infrastructure engineer|cloud engineer|systems engineer|production engineer|release engineer|founding engineer)\b/i;
const STANDALONE=/^(managing director|executive director|senior director|director|partner)$/i;
const NEVER=/\b(marketing|sales|growth|revenue|people|talent|recruiting|recruiter|hr|human resources|finance|financial|accounting|brand|content|community|customer|client|account|assistant|product owner|chief of staff|mechanical|facilities|contracts|capture|alliances|legal|gis|writer|veteran|medical|clinical|program|managed services|creative|design|designer|gtm|partnerships|strategy|staffing)\b/i;
const passes=(title)=>{ const t=roleOnly(title); if(!t) return false; if(NEVER.test(t)) return false; return EXEC.test(t)||(LEAD.test(t)&&TECH.test(t))||IC.test(t)||STANDALONE.test(t.trim()); };
const pause=[]; const pausedNames=[];
let landed=0, titleFail=0, urlMismatch=0, noData=0;
for(const p of persons){
  const fp=D.freshProspects[p.personId];
  const url=normUrl(p.linkedinUrl);
  const rowId=url?D.urlToRow[url]:'';
  if(!fp){
    // An older member matching a row we just pushed: it landed in a prior run and was never
    // stamped. Stamp it now; never pause old actives here (the standing audit owns them).
    if(rowId&&D.rows[rowId]&&!D.rows[rowId].skip&&!D.rows[rowId].landed){ landed++; D.rows[rowId].landed=true; D.rows[rowId].healed=true; }
    continue;
  }
  if(!p.name&&!p.linkedinUrl){ noData++; pause.push(fp.prospectId); pausedNames.push((p.personId||'?')+' (no person data)'); continue; }
  if(!rowId){ urlMismatch++; pause.push(fp.prospectId); pausedNames.push((p.name||url||'?')+' (URL not one we pushed)'); continue; }
  if(!passes(p.title)){ titleFail++; pause.push(fp.prospectId); pausedNames.push((p.name||'?')+' ('+(roleOnly(p.title)||'no title')+')'); if(D.rows[rowId]) D.rows[rowId].skip='paused: Alta-side title failed the buyer rule'; continue; }
  landed++;
  if(D.rows[rowId]) D.rows[rowId].landed=true;
}
D.landed=landed; D.pausedTitle=titleFail; D.pausedUrl=urlMismatch; D.pausedNoData=noData; D.pausedNames=pausedNames.slice(0,25);
// Rows pushed but not matched by any fresh person: not landed.
let sentNoLand=0;
for(const id of Object.keys(D.rows)){ const rec=D.rows[id]; if(!rec.skip&&!rec.landed){ rec.skip='not in campaign after deploy'; sentNoLand++; } }
D.missing=sentNoLand;
if(!pause.length) return [{json:{_none:true, prospectIds:[], action:'pause'}}];
return [{json:{prospectIds:pause, action:'pause'}}];

// Build Stamps: confirmed landings get this campaign's mirror row unioned into their
// Campaigns links (never a replacement); everything else visible gets its reason in
// Deploy Error. The stamp is the door's dedupe for every future run.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{_none:true}}]; }
const patches=[];
let stamped=0;
for(const rid of Object.keys(D.rows||{})){
  const r=D.rows[rid];
  const fields={};
  if(D.hasDeployError) fields['Deploy Error']=r.skip||'';
  if(r.landed&&D.stampMirrorRid){
    const set={}; for(const c of (r.camps||[])) set[(c&&typeof c==='object')?c.id:c]=1; set[D.stampMirrorRid]=1;
    fields['Campaigns']=Object.keys(set); stamped++;
  }
  if(Object.keys(fields).length) patches.push({id:rid, fields});
}
D.campsStamped=stamped;
if(D.landed&&!stamped) D.warnings.push('landed prospects were not stamped with a Campaigns link (no mirror row)');
const out=[];
for(let i=0;i<patches.length;i+=10) out.push({json:{crBase:D.crBase, tableId:D.tableId, body:{records:patches.slice(i,i+10), typecast:true}}});
if(!out.length) return [{json:{_none:true}}];
return out;

// Build Receipt: the Lead Lists row, one per view+campaign, refreshed by every run of this
// door (a daily feed hits the same row forever, zero new rows). List URL is the client-safe
// share link from the table description; View Link the internal deep link to the selector.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id; const D=sd[dk];
if(D.abort){ return [{json:{_none:true}}]; }
let hubId=D.hubCampaignRid||'';
const name=(D.tableName||D.tableId||'table')+' - '+(D.view||'view');
const internal=(D.shareViewLink&&D.tableId&&D.viewId)?(D.shareViewLink+'/'+D.tableId+'/'+D.viewId):'';
return [{json:{ Name:name, Campaign:hubId?[hubId]:[], ViewLink:D.shareViewLink||'', InternalLink:internal, Deployed:Number(D.landed||0) }}];

// Build Run Log: the run's one row plus the launch-row closeout, per the logging standard.
// Landing counts come from the readback, never from pull-in responses.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
const D=sd[dk]||{errors:['deploy state missing'],warnings:[],rows:{},skipCounts:{},launchId:''};
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const failed=(D.errors||[]).slice();
const sc=D.skipCounts||{};
const md=[];
md.push('**Landed '+nf(D.landed)+' of '+nf(D.rowsTotal)+' view rows in '+(D.campName||D.target||'?')+'**');
md.push('');
md.push('**Campaign:** '+(D.campName||'?')+' ('+(D.target||'?')+') · **View:** '+(D.view||'?')+' on '+(D.tableName||D.tableId||'?'));
md.push('');
md.push('**Funnel**');
md.push('- **View rows:** '+nf(D.rowsTotal));
const skipTotal=Object.keys(sc).reduce((s,k)=>s+sc[k],0);
if(skipTotal){ md.push('- **Skipped before push ('+nf(skipTotal)+'):**'); for(const k of Object.keys(sc)) md.push('   - '+k+': '+nf(sc[k])); }
md.push('- **Pushed:** '+nf(D.pushed));
md.push('- **Landed (readback):** '+nf(D.landed));
if(D.missing) md.push('- **Pushed but not in the campaign:** '+nf(D.missing));
const pz=(D.pausedTitle||0)+(D.pausedUrl||0)+(D.pausedNoData||0);
if(pz){ md.push('- **Auto-paused after landing:** '+nf(pz)+' (title rule '+nf(D.pausedTitle)+' · URL mismatch '+nf(D.pausedUrl)+' · no person data '+nf(D.pausedNoData)+')'); for(const n of (D.pausedNames||[])) md.push('   - '+n); }
md.push('- **Campaigns links stamped:** '+nf(D.campsStamped));
if((D.warnings||[]).length){ md.push(''); md.push('**Warnings ('+D.warnings.length+')**'); for(const w of D.warnings) md.push('- '+w); }
if(failed.length){ md.push(''); md.push('**FAILED ('+failed.length+')**'); for(const e of failed) md.push('- '+e); }
const desc=md.join('\n');
const durS=Math.round((Date.now()-(D.startedAt||Date.now()))/1000);
sd[dk]=null;
const status=D.abort?'Failed':(failed.length||pz||D.missing?'Succeeded with errors':'Succeeded');
return [{json:Object.assign({_launchId:D.launchId||''},{
  'Automation':'Deploy View to Campaign',
  'Status':status,
  'Run at':D.runAt||$now.toISO(),
  'Duration s':durS,
  'Records In':D.rowsTotal||0,
  'Records Out':D.landed||0,
  'Errors':failed.length+ (pz?1:0),
  'Target':(D.tableName||D.tableId||'')+' -> '+(D.campName||D.target||''),
  'Execution ID':String($execution.id),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Description':desc.slice(0,95000)
 })}];

// The daily feed: every Campaigns row whose Signal link is set drinks from its Signal View.
// One launch row per feed, entering the door exactly like a manual launch, dedupe Strict plus
// the Campaigns-stamp gate. Refused with a named error, deploying nothing: an empty Signal
// View, an unresolvable Signal link, a missing Campaign ID or Client, and any view feeding
// two campaigns at once.
const camps=$('Get Fed Campaigns').all().map(i=>i.json).filter(r=>r&&(r.id||r.fields));
const sigs={};
try{ for(const it of $('Get Signals Rows').all()){ const j=it.json||{}; const f=j.fields||j; if(j.id) sigs[j.id]={ table:String(f['Target Table']||'').trim(), name:String(f['Name']||'') }; } }catch(e){}
const out=[]; const seenView={};
for(const c of camps){
  const f=c.fields||c;
  if(!f['Campaign ID']&&!f['Signal']) continue;
  const link=Array.isArray(f['Signal'])?f['Signal'][0]:null;
  const sigId=link&&typeof link==='object'?String(link.id||''):String(link||'');
  const sig=sigs[sigId];
  const view=String(f['Signal View']||'').trim();
  const target=String(f['Campaign ID']||'').trim();
  const clientLink=Array.isArray(f['Client'])?f['Client'][0]:null;
  const clientId=clientLink&&typeof clientLink==='object'?String(clientLink.id||''):String(clientLink||'');
  const name=String(f['Campaign']||target||'?');
  const err=(why)=>out.push({json:{ok:false, campaign:name, why}});
  if(!sig||!sig.table){ err('Signal link does not resolve to a Signals row with a Target Table'); continue; }
  if(!view){ err('Signal View is empty; fill it or remove the Signal link'); continue; }
  if(!target){ err('Campaign ID is empty'); continue; }
  if(!clientId){ err('no Client link on the campaign row'); continue; }
  const vk=sig.table+'|'+view;
  if(seenView[vk]){
    err('view "'+view+'" already feeds "'+seenView[vk]+'"; one view feeds one campaign');
    for(const o of out){ if(o.json.ok&&o.json.view===view&&o.json.tableId===sig.table){ o.json.ok=false; o.json.why='view "'+view+'" feeds two campaigns; one view feeds one campaign'; } }
    continue;
  }
  seenView[vk]=name;
  out.push({json:{ok:true, clientId, tableId:sig.table, view, target, campaign:name, signal:sig.name}});
}
if(!out.length) return [{json:{_none:true, ok:false}}];
return out;

// One loud run-log row when the daily feed refuses campaigns; silence when there was simply
// nothing to feed. A refused feed deploys nothing, so the error must be impossible to miss.
const bad=$input.all().map(i=>i.json).filter(j=>j&&j.ok===false&&!j._none);
if(!bad.length) return [];
const lines=bad.map(b=>'- '+(b.campaign||'?')+': '+(b.why||''));
return [{json:{
 'Automation':'Deploy View to Campaign',
 'Status':'Failed',
 'Run at':$now.toISO(),
 'Trigger':'schedule',
 'Errors':bad.length,
 'Execution ID':String($execution.id),
 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description':'**Daily feed refused '+bad.length+' campaign(s), nothing deployed for them**\n'+lines.join('\n')
}}];
